sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    var itinerary = g_form.getValue('u_selected_itinerary');
    if (!itinerary) {
        g_form.addInfoMessage('Please select an Itinerary Package first.');
        return;
    }

    var ga = new GlideAjax('global.TBA_TravelAjaxUtils');// to call global scope script
    ga.addParam('sysparm_name', 'calculateEndDate');
    ga.addParam('sysparm_start_date', newValue);
    ga.addParam('sysparm_itinerary', itinerary);

    ga.getXML(populateEndDateField);
    // Extract the answer from the server's XML response
    function populateEndDateField(response) {
        var answer = response.responseXML.documentElement.getAttribute("answer");
        if (answer) {
            g_form.setValue('end_time', answer);
        }
    }

}
